def compute(vars):
    old = vars["v1"]
    new = vars["v2"]
    if old == 0:
        return None
    change_ratio = (new - old) / old
    projected_2014 = new * (1 + change_ratio)
    return {
        "value": projected_2014,
        "trace": {
            "change_ratio": change_ratio,
            "projected_2014": projected_2014,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
